// ---- crowd cheer samples (small and big) ----
const CHEER_SRC={c1:'data:audio/mpeg;base64,',c2:'data:audio/mpeg;base64,'};
const CHEERB={c1:null,c2:null,ld:false};
function cheerLoad(c){if(CHEERB.ld||!c)return;CHEERB.ld=true;['c1','c2'].forEach(k=>{try{const bin=atob(CHEER_SRC[k].split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const p=c.decodeAudioData(u.buffer,b=>{CHEERB[k]=b},()=>{});if(p&&p.catch)p.catch(()=>{})}catch(e){}})}
(function(){const _ch=SFX.cheer;SFX.cheer=function(lv){
 try{const c=sndCtx();if(c){cheerLoad(c);const k=(lv||1)>=2?'c2':'c1';const b=CHEERB[k];if(b){if(!sndOk('cheer',350))return;const s=c.createBufferSource();s.buffer=b;s.playbackRate.value=.97+Math.random()*.06;const g=c.createGain();g.gain.value=k==='c2'?.6:.4;s.connect(g);g.connect(SND.master);s.start();return}}}catch(e){}
 return _ch.apply(this,arguments)};
 try{if(typeof window!=='undefined')window.addEventListener('pointerdown',()=>{try{const c=sndCtx();if(c)cheerLoad(c)}catch(e){}},{once:true,capture:true})}catch(e){}})();
